/** Trusted shell. Generated files only run in an opaque iframe, never this document. */
export const APP_SDK=`<script>(()=>{let seq=0;const pending=new Map();window.addEventListener('message',e=>{if(e.source!==parent||e.data?.kind!=='vln-response')return;const p=pending.get(e.data.id);if(p){pending.delete(e.data.id);clearTimeout(p.timer);e.data.error?p.reject(Error(e.data.error)):p.resolve(e.data.result)}});window.velnavoq=Object.freeze({request(action,args={}){const id=++seq;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject(Error('Request timed out'))},15000);pending.set(id,{resolve,reject,timer});parent.postMessage({kind:'vln-request',id,action,args},'*')})},auth:{me(){return window.velnavoq.request('me')},signIn(){return window.velnavoq.request('signIn')},signOut(){return window.velnavoq.request('signOut')}},data:{list(table){return window.velnavoq.request('list',{table})},create(table,row){return window.velnavoq.request('create',{table,row})},update(table,id,row){return window.velnavoq.request('update',{table,id,row})},remove(table,id){return window.velnavoq.request('delete',{table,id})}}})})();</script>`;
export function privateAppShell(pid:string){return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Velnavoq app</title><style>html,body{height:100%;margin:0;font:14px system-ui;background:#0b111c;color:#eef3fa}body{display:flex;flex-direction:column}header{display:flex;gap:12px;align-items:center;padding:10px 16px;border-bottom:1px solid #293a50}header span{flex:1;font-size:12px;color:#b7c6d8}button,input{font:inherit;min-height:44px;border:1px solid #49607d;border-radius:8px;padding:8px 12px;background:#152238;color:#eef3fa}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #8fc9ff}iframe{flex:1;width:100%;border:0;background:white}dialog{width:min(360px,calc(100vw - 56px));background:#101d30;color:#eef3fa;border:1px solid #49607d;border-radius:16px;padding:24px}dialog::backdrop{background:#000b}label{display:grid;gap:8px;margin:18px 0}input{width:100%;box-sizing:border-box}p{line-height:1.6;color:#b7c6d8}#error{color:#ffb2bb}form>div{display:flex;gap:8px;flex-wrap:wrap}</style><header><b>Velnavoq</b><span id="status">Checking session</span><button id="verify-email" hidden>Verify email</button><button id="account">Sign in</button></header><iframe id="app" title="Generated app" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe><dialog id="auth"><form id="form"><h2>App account</h2><p>Your account is for this app only. Email verification and recovery require the operator’s mail setup. Availability is checked below. Use a unique password.</p><label>Email<input id="email" type="email" autocomplete="email" required maxlength="254"></label><label>Password<input id="password" type="password" autocomplete="current-password" required minlength="12" maxlength="128"></label><p id="error" role="alert"></p><div><button type="submit" id="login">Sign in</button><button type="submit" id="register">Create account</button><button type="button" id="forgot" hidden>Forgot password?</button><button type="button" id="cancel">Cancel</button></div></form></dialog><script>
(()=>{'use strict';const base='/a/${pid}/api/',frame=document.getElementById('app'),auth=document.getElementById('auth'),status=document.getElementById('status'),account=document.getElementById('account');let csrf='',user=null,busy=false,bridgeActive=0,mailMode='',mailToken='',mailAvailable=false,emailVerified=false;const bridgeTimes=[];
const call=async(path,method='GET',body)=>{const r=await window.fetch(base+path,{method,credentials:'same-origin',headers:{'content-type':'application/json',...(csrf?{'x-app-csrf':csrf}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');if(d.csrf)csrf=d.csrf;return d};
const paint=()=>{status.textContent=user?'Signed in: '+(user.email||'app user'):'App · signed out';account.textContent=user?'Sign out':'Sign in';document.getElementById('verify-email').hidden=!user||!mailAvailable||emailVerified};
const show=(mode='')=>{mailMode=mode;document.getElementById('error').textContent='';document.getElementById('password').required=mode!=='recover';document.getElementById('password').disabled=mode==='recover';document.getElementById('email').required=mode!=='reset';document.getElementById('email').disabled=mode==='reset';document.getElementById('register').hidden=!!mode;document.getElementById('login').textContent=mode==='reset'?'Set new password':mode==='recover'?'Email reset link':'Sign in';auth.showModal()};
const out=async()=>{await call('auth/logout','POST',{});user=null;csrf='';paint();frame.contentWindow.postMessage({kind:'vln-auth-changed'},'*');return {signedOut:true}};
account.onclick=()=>{if(user)out().catch(e=>{status.textContent=e.message});else show()};document.getElementById('cancel').onclick=()=>{mailToken='';auth.close()};document.getElementById('forgot').onclick=()=>show('recover');document.getElementById('verify-email').onclick=()=>call('auth/email/request','POST',{}).then(()=>{status.textContent='Verification requested. Check your inbox.'}).catch(e=>{status.textContent=e.message});
const hex=b=>Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
document.getElementById('form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const buttons=auth.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{const email=document.getElementById('email').value.trim().toLowerCase(),password=document.getElementById('password').value,register=e.submitter?.id==='register';if(mailMode==='recover'){await call('auth/recovery/request','POST',{email});document.getElementById('error').textContent='If this app has that account, a reset link will arrive. It expires in 30 minutes.';return}if(password.length<12||password.length>128)throw Error('Use 12 to 128 characters');const salt=register||mailMode==='reset'?hex(crypto.getRandomValues(new Uint8Array(32))):(await call('auth/kdf','POST',{email})).salt;const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const verifier=hex(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',iterations:600000,salt:new TextEncoder().encode(salt)},key,256));if(mailMode==='reset'){await call('auth/recovery/reset','POST',{token:mailToken,salt,verifier});mailToken='';document.getElementById('password').value='';show();document.getElementById('error').textContent='Password changed. Sign in again.';return}await call(register?'auth/register':'auth/login','POST',{email,verifier,...(register?{salt}:{})});document.getElementById('password').value='';user=await call('auth/me');paint();auth.close();frame.contentWindow.postMessage({kind:'vln-auth-changed'},'*')}catch(e){document.getElementById('error').textContent=e.message}finally{busy=false;buttons.forEach(b=>b.disabled=false)}};
window.addEventListener('message',async e=>{const d=e.data;if(e.source!==frame.contentWindow||e.origin!=='null'||d?.kind!=='vln-request'||!Number.isSafeInteger(d.id)||d.id<1||typeof d.action!=='string')return;const now=Date.now();while(bridgeTimes.length&&bridgeTimes[0]<now-60000)bridgeTimes.shift();if(bridgeActive>=4||bridgeTimes.length>=60){frame.contentWindow.postMessage({kind:'vln-response',id:d.id,error:'app_bridge_rate_limited'},'*');return}bridgeTimes.push(now);bridgeActive++;let result,error;try{if(d.action==='signIn'){show();result={pending:true}}else if(d.action==='signOut')result=await out();else if(d.action==='me'){try{user=await call('auth/me');paint();result={userId:user.userId,email:user.email,role:user.role}}catch(e){if(String(e.message).includes('app_authentication_required')||String(e.message).includes('app_session_expired')){user=null;paint();result=null}else throw e}}else{const a=d.args;if(!a||typeof a.table!=='string'||!/^[a-z][a-z0-9_]{0,31}$/.test(a.table))throw Error('Invalid table');const methods={list:'GET',create:'POST',update:'PUT',delete:'DELETE'},method=methods[d.action];if(!method)throw Error('Action denied');if(['update','delete'].includes(d.action)&&! /^[a-f0-9-]{36}$/.test(a.id))throw Error('Invalid row');result=await call('data/'+a.table+(['update','delete'].includes(d.action)?'/'+a.id:''),method,method==='POST'||method==='PUT'?a.row:undefined)}}catch(e){error=e.message}finally{bridgeActive--}frame.contentWindow?.postMessage({kind:'vln-response',id:d.id,...(error?{error}:{result})},'*')});
const mailLink=/^#(verify|recover)=([a-f0-9]{64})$/.exec(location.hash);if(mailLink)history.replaceState(null,'',location.pathname);
call('auth/email/capabilities').then(async c=>{if(!c.available)return;mailAvailable=true;document.getElementById('forgot').hidden=false;if(mailLink){if(mailLink[1]==='verify'){await call('auth/email/confirm','POST',{token:mailLink[2]});status.textContent='Email verified.'}else{mailToken=mailLink[2];show('reset')}}try{user=await call('auth/me')}catch{}if(user){const verified=await call('auth/email/status');emailVerified=verified.emailVerified}paint()}).catch(e=>{status.textContent=e.message});
call('auth/me').then(d=>{user=d;paint()}).catch(()=>{user=null;paint()}).finally(()=>{frame.src='/a/${pid}/frame/index.html'});
setInterval(()=>{if(user&&!document.hidden)call('auth/renew','POST',{}).catch(()=>{user=null;csrf='';paint()})},86400000);
})();</script></html>`}

export function injectAppSdk(html:string){return /<head[^>]*>/i.test(html)?html.replace(/(<head[^>]*>)/i,'$1'+APP_SDK):html.replace(/^(<!doctype[^>]*>)?/i,'$&'+APP_SDK)}
